'use server';
/**
 * @fileOverview This file defines the primary conversational AI flow for gathering project details.
 *
 * @Exported Members:
 *   - `getNextStep`: The main flow function that processes a conversational turn.
 *   - `NextStepInput`: The Zod schema for the flow's input.
 *   - `NextStepOutput`: The Zod schema for the flow's output.
 */

import { ai } from '@/ai/genkit';
import {
  NextStepInputSchema,
  type NextStepInput,
  NextStepOutputSchema,
  type NextStepOutput,
  MessageSchema,
} from '@/ai/schemas/next-step';
import { InitialEstimateInputSchema } from '@/ai/schemas/initial-estimate';
import { z } from 'zod';

// The data fields the AI needs to collect from the user, in order.
const REQUIRED_FIELDS: {
  key: keyof NextStepInput['collectedData'];
  name: string;
  question: string;
}[] = [
  {
    key: 'projectName',
    name: 'Project Name',
    question: "First, what would you like to name this project estimate?",
  },
  {
    key: 'squareFootage',
    name: 'Square Footage',
    question: "What's the total square footage of the project area?",
  },
  {
    key: 'planType',
    name: 'Plan Type',
    question:
      'What type of floor plan are you considering? (e.g., Open Plan or Mixed Use)',
  },
  {
    key: 'privateOffices',
    name: 'Private Offices',
    question: 'How many private offices will be included?',
  },
  {
    key: 'ceilingType',
    name: 'Ceiling Type',
    question:
      'What type of ceiling will it have? (e.g., Standard or Open with exposed ductwork)',
  },
  {
    key: 'ceilingHeight',
    name: 'Ceiling Height',
    question: 'And what is the ceiling height in feet?',
  },
];

// This schema now takes the full conversation history for context.
const ExtractDataInputSchema = z.object({
  history: z.array(MessageSchema),
});

// A prompt that extracts structured data from the conversation history.
const extractDataPrompt = ai.definePrompt({
  name: 'extractDataPrompt',
  input: { schema: ExtractDataInputSchema },
  output: { schema: InitialEstimateInputSchema.partial() },

  prompt: `You are an AI assistant that extracts structured information from a conversation.
Your task is to analyze the conversation history to extract values for the following fields:
- projectName (string)
- squareFootage (number)
- planType ('Open Plan' or 'Mixed Use')
- privateOffices (number)
- ceilingType ('Standard' or 'Open')
- ceilingHeight (number)

Analyze the user's last message in the context of the conversation history.
If the user provides a value for one of these fields, extract it.

You MUST respond with a valid JSON object matching the output schema.
If the last user message contains no relevant information for these fields, return an empty JSON object {}.
Do not add any other text, just the JSON object.

Conversation History:
{{#each history}}
- {{role}}: {{content}}
{{/each}}
`,
  model: 'googleai/gemini-2.5-flash',
  config: {
    temperature: 0.0,
  },
});

export async function getNextStep(
  input: NextStepInput
): Promise<NextStepOutput> {
  return getNextStepFlow(input);
}

// The flow now contains the logic to decide what to do next.
const getNextStepFlow = ai.defineFlow(
  {
    name: 'getNextStepFlow',
    inputSchema: NextStepInputSchema,
    outputSchema: NextStepOutputSchema,
  },
  async (input) => {
    console.log('[Flow] getNextStepFlow: Received input', JSON.stringify(input, null, 2));

    // 1. Call the AI to extract data from the conversation history.
    console.log('[Flow] Calling extractDataPrompt...');
    const { output: extractedData } = await extractDataPrompt({ history: input.history });
    console.log('[Flow] Extracted Data from AI:', JSON.stringify(extractedData, null, 2));

    if (!extractedData) {
      console.warn('[Flow] AI did not return extracted data.');
      // This can happen if the model fails to return valid JSON. The flow will throw before this.
      // This case is for when the model returns valid JSON, but it's empty/null.
      return {
        response:
          "I'm sorry, I had trouble understanding that. Could you please rephrase?",
        updatedData: input.collectedData,
        isComplete: false,
      };
    }

    // 2. Merge the newly extracted data with the data we've already collected.
    const updatedData = { ...input.collectedData, ...extractedData };
    console.log('[Flow] Merged Data:', JSON.stringify(updatedData, null, 2));


    // 3. Determine the next step by finding the first missing field.
    const nextMissingField = REQUIRED_FIELDS.find(
      (field) =>
        updatedData[field.key] === undefined ||
        updatedData[field.key] === null ||
        updatedData[field.key] === ''
    );
    console.log('[Flow] Next Missing Field:', nextMissingField?.key);


    // 4. If all fields are collected, mark as complete.
    if (!nextMissingField) {
      console.log('[Flow] All fields collected. Completing conversation.');
      return {
        response: "Thanks! I have everything I need to generate your estimate.",
        updatedData: updatedData,
        isComplete: true,
      };
    }

    // 5. Otherwise, ask the next question in the sequence.
    console.log(`[Flow] Asking next question for: ${nextMissingField.key}`);
    return {
      response: nextMissingField.question,
      updatedData: updatedData,
      isComplete: false,
    };
  }
);
