/**
 * @fileOverview Schemas for the conversational AI flow.
 * Defines the data structures for the input and output of the getNextStep flow.
 */
import { z } from 'zod';
import { InitialEstimateInputSchema } from '@/ai/schemas/initial-estimate';

export const MessageSchema = z.object({
  role: z.enum(['user', 'model']),
  content: z.string(),
});

// Input for the main conversational flow
export const NextStepInputSchema = z.object({
  history: z.array(MessageSchema).describe('The conversation history so far.'),
  collectedData: InitialEstimateInputSchema.partial().describe(
    'A JSON object of the data collected from the user so far.'
  ),
});
export type NextStepInput = z.infer<typeof NextStepInputSchema>;

// Output of the main conversational flow
export const NextStepOutputSchema = z.object({
  response: z
    .string()
    .describe(
      "The AI's next response to the user. This could be a question for more information, a clarifying question, or a confirmation message if all data is collected."
    ),
  updatedData: InitialEstimateInputSchema.partial().describe(
    "The updated JSON object with any new data extracted from the user's last message."
  ),
  isComplete: z
    .boolean()
    .describe(
      'A boolean flag indicating if all required information has been collected.'
    ),
});
export type NextStepOutput = z.infer<typeof NextStepOutputSchema>;
